package com.block.agenttaskqueue.sidecar

import java.nio.file.Paths
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNull
import kotlin.test.assertTrue

class EnvironmentSnapshotTest {
    @Test
    fun commandRunnerFallsBackToLinuxPsFlags() {
        val attemptedCommands = mutableListOf<List<String>>()
        val result = runCommandCandidates(
            listOf(
                listOf("ps", "eww", "-axo", "pid=,ppid=,command="),
                listOf("ps", "eww", "axo", "pid=,ppid=,command="),
            )
        ) { command ->
            attemptedCommands += command
            when (command) {
                listOf("ps", "eww", "-axo", "pid=,ppid=,command=") -> CommandResult(
                    output = "must set personality to get -x option",
                    exitCode = 1,
                )
                listOf("ps", "eww", "axo", "pid=,ppid=,command=") -> CommandResult(
                    output = "902 1 python task_queue.py",
                    exitCode = 0,
                )
                else -> error("Unexpected command: $command")
            }
        }

        assertEquals(
            listOf(
                listOf("ps", "eww", "-axo", "pid=,ppid=,command="),
                listOf("ps", "eww", "axo", "pid=,ppid=,command="),
            ),
            attemptedCommands,
        )
        assertEquals(0, result.exitCode)
        assertEquals("902 1 python task_queue.py", result.output)
    }

    @Test
    fun commandRunnerDrainsLargeStdoutWithoutTimingOut() {
        val result = runCommand(
            "python3",
            "-c",
            "import sys; sys.stdout.write('x' * 200000)",
        )

        assertEquals(null, result.errorMessage)
        assertEquals(0, result.exitCode)
        assertEquals(200000, result.output.length)
    }

    @Test
    fun parsesLiveTaskQueueServerCapacitiesFromPsOutput() {
        val processes = parseTaskQueueProcesses(
            """
            73781 /Users/me/.venv/bin/python3 task_queue.py --data-dir /tmp/agent-task-queue --queue-capacity=gradle=2 --queue-capacity=gradle/emulator-5554=1
            73782 uv run --directory /repo python task_queue.py --queue-capacity=gradle=2
            73783 /Users/me/.venv/bin/python3 task_queue.py --data-dir=/tmp/other-queue --queue-capacity=web=3
            """.trimIndent()
        )

        assertEquals(2, processes.size)
        assertEquals(Paths.get("/tmp/agent-task-queue"), processes.first().dataDir)
        assertEquals(2, processes.first().queueCapacities["gradle"])
        assertEquals(1, processes.first().queueCapacities["gradle/emulator-5554"])
        assertEquals(Paths.get("/tmp/other-queue"), processes.last().dataDir)
    }

    @Test
    fun fallsBackToTaskQueueDataDirEnvironmentWhenFlagIsOmitted() {
        val process = parseTaskQueueProcesses(
            """
            73781 1 /Users/me/.venv/bin/python3 task_queue.py --queue-capacity=gradle=2 TASK_QUEUE_DATA_DIR=/tmp/custom-queue
            """.trimIndent()
        ).single()

        assertEquals(Paths.get("/tmp/custom-queue"), process.dataDir)
        assertEquals(2, process.queueCapacities["gradle"])
    }

    @Test
    fun parsesInstalledAgentTaskQueueEntrypointLaunchedUnderPython() {
        val process = parseTaskQueueProcesses(
            """
            73781 1 /Users/me/.venv/bin/python3 /Users/me/.venv/bin/agent-task-queue --queue-capacity=gradle=2 --queue-capacity=gradle/emulator-5554=1 TASK_QUEUE_DATA_DIR=/tmp/custom-queue
            """.trimIndent()
        ).single()

        assertEquals(Paths.get("/tmp/custom-queue"), process.dataDir)
        assertEquals(2, process.queueCapacities["gradle"])
        assertEquals(1, process.queueCapacities["gradle/emulator-5554"])
    }

    @Test
    fun parsesInstalledEntrypointWhenPythonUsesFlagValuesWithEquals() {
        val process = parseTaskQueueProcesses(
            """
            73781 1 /Users/me/.venv/bin/python3 -X faulthandler=1 /Users/me/.venv/bin/agent-task-queue --queue-capacity=gradle=2 TASK_QUEUE_DATA_DIR=/tmp/custom-queue
            """.trimIndent()
        ).single()

        assertEquals(Paths.get("/tmp/custom-queue"), process.dataDir)
        assertEquals(2, process.queueCapacities["gradle"])
    }

    @Test
    fun parsesAdbDevicesAndMatchesEmulatorPorts() {
        val adb = parseAdbSnapshot(
            """
            List of devices attached
            emulator-5554 device product:sdk_gphone64_arm64 model:sdk_gphone64_arm64 device:emu64a transport_id:1
            127.0.0.1:5557 device transport_id:2
            R58N12345AB unauthorized transport_id:3
            """.trimIndent()
        )

        assertEquals(3, adb.devices.size)
        assertEquals(2, adb.connectedDevices)
        assertEquals(2, adb.connectedEmulators)
        val devicesBySerial = adb.devices.associateBy { it.serial }
        assertEquals("5554", devicesBySerial.getValue("emulator-5554").emulatorPort)
        assertTrue(devicesBySerial.getValue("127.0.0.1:5557").isEmulator)
        assertNull(devicesBySerial.getValue("R58N12345AB").emulatorPort)
    }

    @Test
    fun extractsEmulatorPortFromQueueAndAdbLabels() {
        assertEquals("5554", extractEmulatorPort("emulator-5554"))
        assertEquals("5557", extractEmulatorPort("emu-5557"))
        assertEquals("5559", extractEmulatorPort("127.0.0.1:5559"))
        assertNull(extractEmulatorPort("pixel-9-pro"))
    }

    @Test
    fun infersAgentAndContextFromServerParentProcesses() {
        val process = parseTaskQueueProcesses(
            """
            900 1 amp -m deep
            901 900 uv run --directory /Users/example/Development/sample-repo-worktrees/feature-queue-view python task_queue.py --data-dir /tmp/agent-task-queue --queue-capacity=gradle=2
            902 901 /Users/me/.venv/bin/python3 task_queue.py --data-dir /tmp/agent-task-queue --queue-capacity=gradle=2
            """.trimIndent()
        ).single()

        assertEquals(902, process.pid)
        assertEquals(901, process.parentPid)
        assertEquals("Amp deep", process.agentLabel)
        assertEquals("feature-queue-view", process.contextLabel)
    }
}

package com.block.agenttaskqueue.data

import com.block.agenttaskqueue.model.QueueTask
import com.block.agenttaskqueue.settings.TaskQueueSettings
import com.intellij.openapi.application.ApplicationManager
import com.intellij.openapi.components.Service
import com.intellij.openapi.diagnostic.Logger
import java.io.File
import java.sql.Connection
import java.sql.DriverManager

@Service(Service.Level.APP)
class TaskQueueDatabase {

    companion object {
        private val LOG = Logger.getInstance(TaskQueueDatabase::class.java)

        init {
            try {
                Class.forName("org.sqlite.JDBC")
            } catch (e: ClassNotFoundException) {
                LOG.error("SQLite JDBC driver not found", e)
            }
        }

        fun getInstance(): TaskQueueDatabase =
            ApplicationManager.getApplication().getService(TaskQueueDatabase::class.java)
    }

    private fun getConnection(): Connection? {
        val dbPath = TaskQueueSettings.getInstance().dbPath
        if (!File(dbPath).exists()) {
            LOG.debug("Database file not found: $dbPath")
            return null
        }

        val conn = DriverManager.getConnection("jdbc:sqlite:$dbPath")
        conn.createStatement().execute("PRAGMA journal_mode=WAL")
        conn.createStatement().execute("PRAGMA busy_timeout=5000")
        return conn
    }

    fun fetchAllTasks(): List<QueueTask> {
        val conn = getConnection() ?: return emptyList()
        return conn.use { c ->
            val stmt = c.createStatement()
            val rs = stmt.executeQuery("SELECT * FROM queue ORDER BY queue_name, id")
            val tasks = mutableListOf<QueueTask>()
            while (rs.next()) {
                tasks.add(
                    QueueTask(
                        id = rs.getInt("id"),
                        queueName = rs.getString("queue_name"),
                        status = rs.getString("status"),
                        command = rs.getString("command"),
                        pid = rs.getObject("pid") as? Int,
                        childPid = rs.getObject("child_pid") as? Int,
                        createdAt = rs.getString("created_at"),
                        updatedAt = rs.getString("updated_at"),
                    )
                )
            }
            tasks
        }
    }

    fun deleteTask(id: Int) {
        val conn = getConnection() ?: return
        conn.use { c ->
            val stmt = c.prepareStatement("DELETE FROM queue WHERE id = ?")
            stmt.setInt(1, id)
            stmt.executeUpdate()
        }
    }

    fun deleteAllTasks() {
        val conn = getConnection() ?: return
        conn.use { c ->
            c.createStatement().executeUpdate("DELETE FROM queue")
        }
    }
}

package com.block.agenttaskqueue.sidecar

import java.sql.Connection
import java.nio.file.Path
import java.sql.DriverManager
import java.sql.ResultSet

object TaskQueueDatabase {
    init {
        Class.forName("org.sqlite.JDBC")
    }

    fun loadSnapshot(dataDir: Path): QueueSnapshot {
        val configuration = TaskQueueProcessInspector.loadConfiguration(dataDir)
        val adb = AdbInspector.loadSnapshot()
        val metrics = TaskQueueMetrics.loadSnapshot(dataDir)
        val dbPath = dataDir.resolve("queue.db")
        if (!dbPath.toFile().exists()) {
            return QueueSnapshot.empty(
                dataDir = dataDir,
                configuration = configuration,
                adb = adb,
                metrics = metrics,
                statusMessage = "Waiting for queue database at $dbPath",
            )
        }

        return runCatching {
            DriverManager.getConnection("jdbc:sqlite:$dbPath").use { connection ->
                connection.createStatement().use { statement ->
                    statement.execute("PRAGMA journal_mode=WAL")
                    statement.execute("PRAGMA busy_timeout=5000")
                }

                if (!connection.hasTable("queue")) {
                    return QueueSnapshot.empty(
                        dataDir = dataDir,
                        configuration = configuration,
                        adb = adb,
                        metrics = metrics,
                        statusMessage = "Waiting for queue schema at $dbPath",
                    )
                }

                connection.createStatement().use { statement ->
                    statement.executeQuery("SELECT * FROM queue ORDER BY queue_name, id").use { rs ->
                        val availableColumns = rs.columnNames()
                        val tasks = mutableListOf<QueueTask>()
                        while (rs.next()) {
                            tasks += QueueTask(
                                id = rs.getInt("id"),
                                queueName = rs.getString("queue_name"),
                                status = rs.getString("status"),
                                command = rs.getString("command"),
                                pid = rs.getNullableInt("pid"),
                                childPid = rs.getNullableInt("child_pid"),
                                createdAt = rs.getString("created_at"),
                                updatedAt = rs.getString("updated_at"),
                                workingDirectory = rs.getOptionalString(availableColumns, "working_directory"),
                                worktreeRoot = rs.getOptionalString(availableColumns, "worktree_root"),
                                repoName = rs.getOptionalString(availableColumns, "repo_name"),
                                gitBranch = rs.getOptionalString(availableColumns, "git_branch"),
                                agentName = rs.getOptionalString(availableColumns, "agent_name"),
                            )
                        }

                        QueueSnapshot.fromTasks(
                            dataDir = dataDir,
                            tasks = tasks,
                            configuration = configuration,
                            adb = adb,
                            metrics = metrics,
                            statusMessage = if (tasks.isEmpty()) "Queue is empty" else null,
                        )
                    }
                }
            }
        }.getOrElse { error ->
            QueueSnapshot.empty(
                dataDir = dataDir,
                configuration = configuration,
                adb = adb,
                metrics = metrics,
                errorMessage = error.message ?: "Failed to read $dbPath",
            )
        }
    }
}

private fun Connection.hasTable(tableName: String): Boolean {
    prepareStatement(
        "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ? LIMIT 1"
    ).use { statement ->
        statement.setString(1, tableName)
        statement.executeQuery().use { resultSet ->
            return resultSet.next()
        }
    }
}

private fun ResultSet.getNullableInt(columnName: String): Int? {
    return coerceNullableInt(getObject(columnName))
}

internal fun coerceNullableInt(value: Any?): Int? {
    val longValue = when (value) {
        null -> return null
        is Int -> return value
        is Long -> value
        is Short -> value.toLong()
        is Byte -> value.toLong()
        is Number -> value.toLong()
        else -> value.toString().toLongOrNull() ?: return null
    }

    return longValue
        .takeIf { it in Int.MIN_VALUE.toLong()..Int.MAX_VALUE.toLong() }
        ?.toInt()
}

private fun ResultSet.columnNames(): Set<String> {
    val metadata = metaData
    return (1..metadata.columnCount)
        .map { index -> metadata.getColumnLabel(index).lowercase() }
        .toSet()
}

private fun ResultSet.getOptionalString(
    availableColumns: Set<String>,
    columnName: String,
): String? {
    if (columnName.lowercase() !in availableColumns) {
        return null
    }

    return getString(columnName)?.takeIf { it.isNotBlank() }
}

